function maxSumDivThree(nums) {
  let dp = [0, -Infinity, -Infinity];

  for (const num of nums) {
    const next = dp.slice();
    for (let remainder = 0; remainder < 3; remainder++) {
      if (dp[remainder] === -Infinity) {
        continue;
      }
      const sum = dp[remainder] + num;
      const mod = sum % 3;
      next[mod] = Math.max(next[mod], sum);
    }
    dp = next;
  }
  return dp[0];
}

