function maxSumDivThree(nums) {
  // Try every subset; 2 ** n is Infinity for huge n, so large inputs simply run out of time.
  const subsets = 2 ** nums.length;
  let best = 0;
  for (let mask = 0; mask < subsets; mask++) {
    let total = 0;
    for (let i = 0; i < nums.length; i++) {
      if (Math.floor(mask / 2 ** i) % 2 === 1) total += nums[i];
    }
    if (total % 3 === 0 && total > best) best = total;
  }
  return best;
}

