    else if (mode === 1) nums.push(3 * int(0, large ? 3332 : 6) + int(1, 2));
    else if (mode === 2) nums.push(3 * int(0, large ? 3332 : 6) + (rand() < 0.85 ? 1 : 2));
    else nums.push(rand() < 0.2 ? 10000 : int(1, 10));
  }
  return [nums];
